def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    opp_def = 0
    for o in op:
        if o == 'D':
            opp_def += 1
    my_def = 0
    for m in my:
        if m == 'D':
            my_def += 1

    # Immediate strong retaliation to sustained defection
    if opp_def * 2 >= n and n >= 6:
        return 'D'

    # Endgame exploitation: if opponent has been quite cooperative, defect
    if n >= 93:
        if opp_def * 4 <= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Short memory: last few opponent moves
    if n >= 4:
        recent = op[-4:]
        r_def = 0
        for x in recent:
            if x == 'D':
                r_def += 1
        if r_def >= 3:
            return 'D'
        if r_def == 0 and last_op == 'C':
            # Opponent very cooperative; occasionally probe
            if n > 15 and rng.random() < 0.08:
                return 'D'
            return 'C'

    # Respond to last defection
    if last_op == 'D':
        # If opponent has almost never defected, forgive once in a while
        if opp_def <= 1 and rng.random() < 0.5:
            return 'C'
        # If we also defected last round, try to restore cooperation sometimes
        if last_my == 'D':
            if opp_def * 3 <= n and rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round
    # If we have been defecting a lot, show willingness to cooperate
    if my_def > opp_def + 2:
        return 'C'
    # If opponent is highly cooperative and we haven't exploited much, probe late
    if n > 30 and opp_def <= 2 and my_def <= 1:
        if rng.random() < 0.12:
            return 'D'
    return 'C'
